  /**
   * Updates visible and physical jetpack state from one input sample.
   * @param {boolean} active
   * @param {boolean} released
   */
  setJetpackInput(active, released) {
    this.jetpack = active;
    if (active) {
      this.jetpackThrusting = true;
    }
    if (released && this.jetpack) {
      this.jetpackThrusting = false;
      this.jetpackPower = 0;
    }
  }

